/**
 * Builds src/lib/admin/access/manifest.generated.ts — the list of admin routes the
 * access-control layer knows about.
 *
 *   node scripts/admin-access-manifest.mjs           write the file
 *   node scripts/admin-access-manifest.mjs --check   exit 1 if the committed file is stale
 *
 * Why a generated file: the middleware runs on the Edge and cannot read the filesystem, and
 * production images do not contain the source tree. The routes are therefore snapshotted at
 * build time. `pnpm build` regenerates it, and the vitest suite fails when the committed copy
 * differs from what the tree would produce — so a developer who adds an admin page sees the
 * failure locally or in CI, not in production.
 *
 * What it records
 *   pages     every `page.tsx` under src/app/[locale]/(admin)/admin, as a route pattern
 *             (`/admin/shop/orders/[id]`); route groups are removed.
 *   api       every `route.ts` under src/app/api/admin, as `/api/admin/...`.
 *   navHrefs  every `href: "/admin/..."` in the sidebar config. The sidebar is the unit a
 *             person grants permission on, so these hrefs are the resource boundaries.
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const here = path.dirname(fileURLToPath(import.meta.url));
export const APP_ROOT = path.resolve(here, "..");
export const OUTPUT = path.join(APP_ROOT, "src/lib/admin/access/manifest.generated.ts");

const PAGES_ROOT = path.join(APP_ROOT, "src/app/[locale]/(admin)/admin");
const API_ROOT = path.join(APP_ROOT, "src/app/api/admin");
const NAV_FILE = path.join(APP_ROOT, "src/features/shared/config/admin-nav.ts");

function walk(dir, predicate, out = []) {
  if (!fs.existsSync(dir)) return out;
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) walk(full, predicate, out);
    else if (predicate(entry.name)) out.push(full);
  }
  return out;
}

/** `(group)` folders and `@slot` folders do not appear in the URL. */
function toSegments(root, file, prefix) {
  const rel = path.relative(root, path.dirname(file)).split(path.sep).filter(Boolean);
  const segments = rel.filter((s) => !(s.startsWith("(") && s.endsWith(")")) && !s.startsWith("@"));
  return `${prefix}${segments.length ? "/" + segments.join("/") : ""}`;
}

export function buildManifest() {
  const pages = walk(PAGES_ROOT, (n) => /^page\.(t|j)sx?$/.test(n))
    .map((f) => toSegments(PAGES_ROOT, f, "/admin"))
    .sort();

  const api = walk(API_ROOT, (n) => /^route\.(t|j)s$/.test(n))
    .map((f) => toSegments(API_ROOT, f, "/api/admin"))
    .sort();

  const navSource = fs.readFileSync(NAV_FILE, "utf8");
  const navHrefs = [...navSource.matchAll(/\bhref:\s*"(\/admin[^"]*)"/g)].map((m) => m[1]);

  return {
    pages: [...new Set(pages)],
    api: [...new Set(api)],
    navHrefs: [...new Set(navHrefs)].sort(),
  };
}

export function renderManifest(manifest) {
  const list = (name, items) =>
    `export const ${name}: readonly string[] = [\n${items.map((i) => `  ${JSON.stringify(i)},`).join("\n")}\n];\n`;
  return (
    `// GENERATED by scripts/admin-access-manifest.mjs — do not edit by hand.\n` +
    `// Regenerate with \`pnpm admin-access:manifest\`. See src/lib/admin/access/README.md.\n\n` +
    list("ADMIN_PAGE_ROUTES", manifest.pages) +
    "\n" +
    list("ADMIN_API_ROUTES", manifest.api) +
    "\n" +
    list("ADMIN_NAV_HREFS", manifest.navHrefs)
  );
}

const isMain = process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (isMain) {
  const next = renderManifest(buildManifest());
  const current = fs.existsSync(OUTPUT) ? fs.readFileSync(OUTPUT, "utf8") : "";
  if (process.argv.includes("--check")) {
    if (current.replace(/\r\n/g, "\n") !== next) {
      console.error(
        "admin access manifest is stale. Run `pnpm admin-access:manifest` and commit the result."
      );
      process.exit(1);
    }
    console.log("admin access manifest is up to date.");
  } else {
    fs.writeFileSync(OUTPUT, next, "utf8");
    console.log(`wrote ${path.relative(APP_ROOT, OUTPUT)}`);
  }
}
